// Runs inside Orca.exe with ELECTRON_RUN_AS_NODE=1, like Orca's plugin worker, with a fake host API.
import { pathToFileURL } from 'node:url'
import { join } from 'node:path'

const [pluginRoot, scenario, terminal] = process.argv.slice(2)
const load = (file) => import(pathToFileURL(join(pluginRoot, 'src', 'worker', file)).href)

// What workspace.readContext returns in each scenario.
const contexts = {
  terminal: { branch: 'main', displayName: 'main', terminals: [{ id: terminal }] },
  'no-terminal': { branch: 'main', displayName: 'main', terminals: [] },
  none: null
}

if (scenario === 'local-entire') {
  // Resolution needs a terminal in a Windows workspace; check the local runner directly instead.
  const { runEntire, failureLine } = await load('entire-cli.mjs')
  const result = await runEntire({ kind: 'local', path: pluginRoot }, ['status', '--json']).catch((error) => ({ error }))
  console.log(result.error ? `✗ spawn: ${result.error.message}` : result.code === 0 ? `✓ local entire status (${result.ms} ms): ${result.stdout.slice(0, 160)}` : `✗ ${failureLine(result)}`)
} else if (!Object.hasOwn(contexts, scenario) || (scenario === 'terminal' && !terminal)) {
  console.log('Scenarios: terminal <handle>, no-terminal, none, local-entire')
  process.exitCode = 1
} else {
  const { default: activate } = await load('main.mjs')
  const commands = new Map()
  activate({
    api: { major: 1, minor: 0 },
    host: {
      has: () => true,
      call: async (method) => {
        if (method !== 'workspace.readContext') throw new Error(`unexpected host call ${method}`)
        return contexts[scenario]
      }
    },
    commands: { register: (id, handler) => (commands.set(id, handler), { dispose() {} }) },
    events: { on: () => ({ dispose() {} }) },
    log: console.log
  })
  console.log(await commands.get('doctor')(undefined, { signal: new AbortController().signal }))
}

import { spawn } from 'node:child_process'
import { win32 } from 'node:path'

// Orca stops waiting for a plugin command after 30 s, so each child process gets a shorter budget.
const CHILD_TIMEOUT_MS = 15_000

export function run(command, args, { cwd, env = process.env, signal, timeoutMs = CHILD_TIMEOUT_MS } = {}) {
  return new Promise((resolve, reject) => {
    const started = Date.now()
    const child = spawn(command, args, { cwd, env, signal, windowsHide: true })
    const stdout = []
    const stderr = []
    let timedOut = false
    const timer = setTimeout(() => {
      timedOut = true
      child.kill()
    }, timeoutMs)
    child.stdout.on('data', (chunk) => stdout.push(chunk))
    child.stderr.on('data', (chunk) => stderr.push(chunk))
    child.on('error', (error) => {
      clearTimeout(timer)
      reject(error)
    })
    child.on('close', (code) => {
      clearTimeout(timer)
      resolve({
        code,
        timedOut,
        stdout: Buffer.concat(stdout).toString('utf8'),
        stderr: Buffer.concat(stderr).toString('utf8'),
        ms: Date.now() - started
      })
    })
  })
}

// The worker env is an allowlist without APPDATA or LOCALAPPDATA, which Windows CLIs (Orca's included)
// use to find their data. Derive them from USERPROFILE when they are missing.
export function desktopEnv(env = process.env, platform = process.platform) {
  if (platform !== 'win32' || !env.USERPROFILE) return env
  return {
    APPDATA: win32.join(env.USERPROFILE, 'AppData', 'Roaming'),
    LOCALAPPDATA: win32.join(env.USERPROFILE, 'AppData', 'Local'),
    ...env
  }
}

import { existsSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { desktopEnv, run } from './process.mjs'

// The worker runs inside Orca's own binary (ELECTRON_RUN_AS_NODE), so Orca's CLI ships beside it.
// Verified on Windows; check the layout before relying on it on macOS.
export function orcaCliPath(execPath = process.execPath, platform = process.platform) {
  const cli = join(dirname(execPath), 'resources', 'bin', platform === 'win32' ? 'orca.exe' : 'orca')
  return existsSync(cli) ? cli : null
}

export async function orcaCli(args, { signal } = {}) {
  const cli = orcaCliPath()
  if (!cli) throw new Error(`Orca CLI not found beside ${process.execPath}`)
  const name = `orca ${args.slice(0, 2).join(' ')}`
  const { code, stdout } = await run(cli, [...args, '--json'], { env: desktopEnv(), signal })
  let reply
  try {
    reply = JSON.parse(stdout)
  } catch {
    throw new Error(`${name} printed no JSON (exit ${code})`)
  }
  if (!reply.ok) throw new Error(`${name}: ${reply.error?.message ?? 'failed'}`)
  return reply.result
}

