async function readManifestDir(
  rootDir: string,
  hostVersion: string,
  isDev: boolean,
  installedContentHash?: string
): Promise<DiscoveredPlugin> {
  let rawText: string
  try {
    rawText = await readPluginManifestText(rootDir)
  } catch (error) {
    return {
      rootDir,
      error:
        error instanceof Error && error.message.includes('exceeds')
          ? error.message
          : `missing ${PLUGIN_MANIFEST_FILENAME}`,
      isDev
    }
  }
  let raw: unknown
  try {
    raw = JSON.parse(rawText)
  } catch (error) {
    return {
      rootDir,
      error: `invalid JSON in ${PLUGIN_MANIFEST_FILENAME}: ${error instanceof Error ? error.message : String(error)}`,
      isDev
    }
  }
  // Why strict for dev trees: they are the author's working copy, so authoring errors belong there.
  const parsed = isDev ? parsePluginManifest(raw) : parseHostPluginManifest(raw)
  if (!parsed.ok) {
    const incompatible = pluginManifestCompatibilityError(raw, hostVersion)
    return { rootDir, error: incompatible ?? `invalid manifest: ${parsed.error}`, isDev }
  }
  const manifest = parsed.manifest
  const pluginKey = qualifiedPluginKey(manifest)
  if (!satisfiesOrcaEngineRange(hostVersion, manifest.engines.orca)) {
    return {
      pluginKey,
      rootDir,
      error: `requires Orca ${manifest.engines.orca} (this is ${hostVersion})`,
      isDev
    }
  }
  const artifacts = await validateDeclaredPluginArtifacts(rootDir, manifest)
  if (!artifacts.ok) {
    return {
      pluginKey,
      rootDir,
      error: `invalid declared artifact: ${artifacts.error}`,
      isDev
    }
  }
  let consentContentIdentity: string | undefined
  if (installedContentHash && requiresPluginContentApproval(manifest)) {
    consentContentIdentity = installedContentHash
  }
  // Why dev trees bind only instructions: dev code is the author's working copy, and
  // binding it would re-prompt on every save.
  if (isDev && hasDeclarativePluginContributions(manifest)) {
    const treeHash = await hashPluginTree(rootDir)
    if (!treeHash.ok) {
      return { pluginKey, rootDir, error: treeHash.error, isDev }
    }
    consentContentIdentity = treeHash.hash
  }
  return {
    pluginKey,
    rootDir,
    manifest,
    consentFingerprint: fingerprintPluginConsent(
      manifest,
      isDev
        ? await devFolderConsentIdentity(rootDir, consentContentIdentity)
        : consentContentIdentity
    ),
    consentContentHash: consentContentIdentity ?? null,
    contentHash: null,
    isDev
  }
}

/** Why the folder: otherwise approving one dev folder approves any other claiming the same key. */
export async function devFolderConsentIdentity(
  rootDir: string,
  contentIdentity?: string
): Promise<string> {

import type { PluginCapabilityKind } from '../../../shared/plugins/capabilities/plugin-capabilities'
import type { ValidDiscoveredPlugin } from '../plugin-discovery'
import type { PluginWorkerSpawnSpec } from './plugin-worker-startup'

export function buildPluginWorkerSpawnSpec(
  plugin: ValidDiscoveredPlugin,
  grantedCapabilities: readonly PluginCapabilityKind[]
): PluginWorkerSpawnSpec {
  if (!plugin.manifest.main) {
    throw new Error(`plugin ${plugin.pluginKey} has no worker entry`)
  }
  return {
    pluginKey: plugin.pluginKey,
    rootDir: plugin.rootDir,
    mainEntry: plugin.manifest.main,
    // Dev roots survive manifest changes; include revision to prevent stale worker reuse.
    manifestRevision: JSON.stringify(plugin.manifest),
    reviewedContentHash: plugin.contentHash ?? plugin.consentContentHash ?? null,
    grantedCapabilities
  }
}

export function pluginWorkerSpawnSpecsEqual(
  left: PluginWorkerSpawnSpec,
  right: PluginWorkerSpawnSpec
): boolean {
  if (
    left.pluginKey !== right.pluginKey ||
    left.rootDir !== right.rootDir ||
    left.mainEntry !== right.mainEntry ||
    left.manifestRevision !== right.manifestRevision ||
    (left.reviewedContentHash ?? null) !== (right.reviewedContentHash ?? null)
  ) {
    return false
  }
  const leftCapabilities = [...left.grantedCapabilities].sort()
  const rightCapabilities = [...right.grantedCapabilities].sort()
  return (
    leftCapabilities.length === rightCapabilities.length &&
    leftCapabilities.every((capability, index) => capability === rightCapabilities[index])
  )
}

