$js = @'
const { DatabaseSync } = await import('node:sqlite')
const db = new DatabaseSync(process.argv[1], { readOnly: true })
const tables = db.prepare("select name from sqlite_master where type='table'").all().map((t) => t.name)
for (const table of tables) {
  const cols = db.prepare(`pragma table_info(${JSON.stringify(table)})`).all().map((c) => c.name)
  for (const col of cols) {
    let rows
    try { rows = db.prepare(`select ${JSON.stringify(col)} as v from ${JSON.stringify(table)} where cast(${JSON.stringify(col)} as text) like '%devPluginPaths%' or cast(${JSON.stringify(col)} as text) like '%disabledPlugins%' or cast(${JSON.stringify(col)} as text) like '%pluginConsents%'`).all() } catch { continue }
    for (const row of rows) {
      const text = String(row.v)
      for (const key of ['devPluginPaths', 'disabledPlugins', 'pluginConsents', 'pluginSystemEnabled']) {
        const i = text.indexOf(`"${key}"`)
        if (i >= 0) console.log(`${table}.${col} ${text.slice(i, i + 400)}`)
      }
    }
  }
}
'@
node --input-type=module -e $js "$dst\profile-state.db" 2>&1 | Select-Object -First 20

