// Prints Orca's plugin settings from a copy of its profile database.
import { DatabaseSync } from 'node:sqlite'

const db = new DatabaseSync(process.argv[2], { readOnly: true })
for (const { payload } of db.prepare('select payload from profile_state_documents').all()) {
  const text = String(payload)
  for (const key of ['devPluginPaths', 'pluginConsents', 'disabledPlugins']) {
    const i = text.indexOf(`"${key}"`)
    if (i >= 0) console.log(text.slice(i, text.indexOf(key === 'pluginConsents' ? '}' : ']', i) + 1))
  }
}

